namespace sv_cc69643ae5054bf7a043e9a276186192.Services;

public class PersonalInfoModel
{
    public string FullName { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
    public string Address { get; set; } = "";
}

public class WorkEntryModel
{
    public string Company { get; set; } = "";
    public string Title { get; set; } = "";
    public DateTime? StartDate { get; set; }
    public DateTime? EndDate { get; set; }
    public bool IsCurrent { get; set; }
    public string Description { get; set; } = "";
}

public class ReferenceModel
{
    public string Name { get; set; } = "";
    public string Relationship { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
}

@using sv_cc69643ae5054bf7a043e9a276186192.Services

<div class="step-indicator">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <div class="step @stepClass" @onclick="() => OnStepClick(stepIndex)">
            <div class="step-circle">
                @if (CompletedSteps.Contains(stepIndex))
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>
        @if (stepIndex < StepNames.Count - 1)
        {
            <div class="step-connector @(CompletedSteps.Contains(stepIndex) ? "completed" : "")"></div>
        }
    }
</div>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepClass(int step)
    {
        if (step == CurrentStep) return "active";
        if (CompletedSteps.Contains(step)) return "completed";
        return "dimmed";
    }

    private async Task OnStepClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

@using sv_cc69643ae5054bf7a043e9a276186192.Services

<div class="work-entry-form">
    <div class="form-row">
        <div class="form-group">
            <label>Company Name</label>
            <input type="text" @bind="Entry.Company" @bind:event="oninput" />
        </div>
        <div class="form-group">
            <label>Job Title</label>
            <input type="text" @bind="Entry.Title" @bind:event="oninput" />
        </div>
    </div>
    <div class="form-row">
        <div class="form-group">
            <label>Start Date</label>
            <input type="date" @bind="Entry.StartDate" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" @bind="Entry.EndDate" disabled="@Entry.IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" @bind="Entry.IsCurrent" @bind:after="OnCurrentChanged" />
                Currently working here
            </label>
        </div>
    </div>
    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" @bind="Entry.Description" @bind:event="oninput"></textarea>
    </div>
    @if (CanRemove)
    {
        <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
    }
</div>

@code {
    [Parameter] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private void OnCurrentChanged()
    {
        if (Entry.IsCurrent)
        {
            Entry.EndDate = null;
        }
    }
}

