toolArgs.file_text:
@using sv_cc69643ae5054bf7a043e9a276186192.Services

<div class="step-content">
    <h3>Review & Submit</h3>

    <div class="review-section">
        <div class="review-header">
            <h4>Personal Information</h4>
            <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
        </div>
        <dl>
            <dt>Full Name</dt><dd>@Personal.FullName</dd>
            <dt>Email</dt><dd>@Personal.Email</dd>
            <dt>Phone</dt><dd>@Personal.Phone</dd>
            <dt>Address</dt><dd>@Personal.Address</dd>
        </dl>
    </div>

    <div class="review-section">
        <div class="review-header">
            <h4>Work History</h4>
            <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
        </div>
        @foreach (var entry in WorkEntries)
        {
            <div class="review-entry">
                <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                <br />
                <span class="date-range">
                    @entry.StartDate?.ToString("MMM yyyy") –
                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                </span>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p>@entry.Description</p>
                }
            </div>
        }
    </div>

    <div class="review-section">
        <div class="review-header">
            <h4>References</h4>
            <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
        </div>
        @foreach (var reference in References)
        {
            <div class="review-entry">
                <strong>@reference.Name</strong> (@reference.Relationship)
                <br />
                @reference.Email | @reference.Phone
            </div>
        }
    </div>

    <div class="review-section">
        <div class="review-header">
            <h4>Cover Letter</h4>
            <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
        </div>
        <p class="cover-letter-preview">@CoverLetter</p>
    </div>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="validation-error">@_errorMessage</div>
    }

    @if (_submitted)
    {
        <div class="success-message">
            <h4>&#10003; Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@_applicationId</strong></p>
        </div>
    }
    else
    {
        <div class="step-buttons">
            <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
            <button type="button" class="btn-primary" @onclick="HandleSubmit" disabled="@_isSubmitting">
                @(_isSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;

    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;
    private string? _errorMessage;

    private async Task HandleSubmit()
    {
        _isSubmitting = true;
        _errorMessage = null;

        try
        {
            var application = new JobApplication(
                new PersonalInfo(Personal.FullName, Personal.Email, Personal.Phone, Personal.Address),
                new WorkHistory(WorkEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate ?? DateTime.MinValue, e.EndDate, e.Description)).ToList()),
                References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                CoverLetter
            );

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }
}

